using FixFinder.Core.LocalFixes;
using FixFinder.Core.Logic;

namespace FixFinder.Tests;

/// <summary>
/// A list filled and never read, in Python, Java, C#, JavaScript, TypeScript, Go, C++, Rust, Ruby, PHP, Lua, Perl, Dart,
/// PowerShell, Scala and F#: a function fills result with each mark doubled and gives back marks, the list it was given. The
/// change gives back result - as Scala's toList and F#'s List.ofSeq make it, where the function gives back a list. Found with
/// no change: a list nothing gives back, one beside a function giving back another local, and a StringBuilder beside a
/// String given back. Left alone in each: each found program put right, a set read through a membership test or what its
/// add says, and a map whose every update reads it.
/// </summary>
public class BuiltNeverReadTests
{
    private static SourceFile Source(string fileName, string code) =>
        new() { Path = Path.Combine(Path.GetTempPath(), fileName), Lines = code.Replace("\r\n", "\n").Split('\n') };

    private static IReadOnlyList<LogicFinding> Scanned(string fileName, string code) =>
        LogicPatterns.Scan(Source(fileName, code))
            .Where(finding => finding.PatternId.EndsWith("-built-never-read", StringComparison.Ordinal))
            .ToList();

    /// <summary>The file, the program, and what the check said of it here: the finding's line, check and words.</summary>
    public static TheoryData<string, string, string> Found => new()
    {
        { "doubled.cpp", "#include <iostream>\n#include <vector>\n\nstd::vector<int> doubled(const std::vector<int>& marks) {\n    std::vector<int> result;\n    for (int mark : marks) {\n        result.push_back(mark * 2);\n    }\n    return marks;\n}\n\nint main() {\n    for (int value : doubled({1, 2, 3})) {\n        std::cout << value << \" \";\n    }\n    std::cout << \"\\n\";\n}\n", "9|logic-cpp-built-never-read|`result` is filled but never read: the function gives back `marks`, what it was given, so everything put in `result` is lost" },
        { "doubled.dart", "List<int> doubled(List<int> marks) {\n  final List<int> result = [];\n  for (var mark in marks) {\n    result.add(mark * 2);\n  }\n  return marks;\n}\n\nvoid main() {\n  print(doubled([1, 2, 3]));\n}\n", "6|logic-dart-built-never-read|`result` is filled but never read: the function gives back `marks`, what it was given, so everything put in `result` is lost" },
        { "doubled.fsx", "let doubled (marks: int list) =\n    let result = ResizeArray<int>()\n    for mark in marks do\n        result.Add(mark * 2)\n    marks\n\nprintfn \"%A\" (doubled [1; 2; 3])\n", "5|logic-fsharp-built-never-read|`result` is filled but never read: the function gives back `marks`, what it was given, so everything put in `result` is lost" },
