        { "Doubled.scala", "import scala.collection.mutable.ListBuffer\n\nobject Doubled {\n  def doubled(marks: List[Int]): List[Int] = {\n    val result = ListBuffer[Int]()\n    for (mark <- marks) {\n      result += mark * 2\n    }\n    marks\n  }\n\n  def main(args: Array[String]): Unit = {\n    println(doubled(List(1, 2, 3)))\n  }\n}\n", "9|logic-scala-built-never-read|`result` is filled but never read: the function gives back `marks`, what it was given, so everything put in `result` is lost" },
