        { "Near.cs", "using System;\nusing System.Collections.Generic;\n\nConsole.WriteLine($\"{HasDuplicate(new List<int> { 1, 2, 1 })} {CountsOf(new List<string> { \"a\", \"b\", \"a\" })[\"a\"]}\");\n\nstatic bool HasDuplicate(List<int> marks)\n{\n    HashSet<int> seen = new HashSet<int>();\n    foreach (var mark in marks)\n    {\n        if (!seen.Add(mark))\n        {\n            return true;\n        }\n    }\n    return false;\n}\n\nstatic Dictionary<string, int> CountsOf(List<string> words)\n{\n    var counts = new Dictionary<string, int>();\n    foreach (var word in words)\n    {\n        counts[word] = counts.GetValueOrDefault(word) + 1;\n    }\n    return counts;\n}\n" },
