        { "near.fsx", "open System.Collections.Generic\n\nlet hasDuplicate (marks: int list) =\n    let seen = HashSet<int>()\n    let mutable found = false\n    for mark in marks do\n        if not (seen.Add(mark)) then\n            found <- true\n    found\n\nlet countsOf (words: string list) =\n    let counts = Dictionary<string, int>()\n    for word in words do\n        counts.[word] <- (if counts.ContainsKey(word) then counts.[word] else 0) + 1\n    counts\n\nprintfn \"%b %d\" (hasDuplicate [1; 2; 1]) ((countsOf [\"a\"; \"b\"; \"a\"]).[\"a\"])\n" },
        { "near.go", "package main\n\nimport \"fmt\"\n\nfunc hasDuplicate(marks []int) bool {\n\tseen := map[int]bool{}\n\tfor _, mark := range marks {\n\t\tif seen[mark] {\n\t\t\treturn true\n\t\t}\n\t\tseen[mark] = true\n\t}\n\treturn false\n}\n\nfunc countsOf(words []string) map[string]int {\n\tcounts := map[string]int{}\n\tfor _, word := range words {\n\t\tcounts[word] = counts[word] + 1\n\t}\n\treturn counts\n}\n\nfunc main() {\n\tfmt.Println(hasDuplicate([]int{1, 2, 1}), countsOf([]string{\"a\", \"b\", \"a\"}))\n}\n" },
        { "Near.java", "import java.util.HashMap;\nimport java.util.HashSet;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.Set;\n\npublic class Near {\n    static boolean hasDuplicate(List<Integer> marks) {\n        Set<Integer> seen = new HashSet<>();\n        for (int mark : marks) {\n            if (!seen.add(mark)) {\n                return true;\n            }\n        }\n        return false;\n    }\n\n    static Map<String, Integer> countsOf(List<String> words) {\n        Map<String, Integer> counts = new HashMap<>();\n        for (String word : words) {\n            counts.put(word, counts.getOrDefault(word, 0) + 1);\n        }\n        return counts;\n    }\n\n    public static void main(String[] args) {\n        System.out.println(hasDuplicate(List.of(1, 2, 1)) + \" \" + countsOf(List.of(\"a\", \"b\", \"a\")));\n    }\n}\n" },
        { "near.js", "function hasDuplicate(marks) {\n  const seen = new Set();\n  for (const mark of marks) {\n    if (seen.has(mark)) {\n      return true;\n    }\n    seen.add(mark);\n  }\n  return false;\n}\n\nfunction countsOf(words) {\n  const counts = {};\n  for (const word of words) {\n    counts[word] = (counts[word] || 0) + 1;\n  }\n  return counts;\n}\n\nconsole.log(hasDuplicate([1, 2, 1]), countsOf([\"a\", \"b\", \"a\"]));\n" },
        { "near.lua", "local function has_duplicate(marks)\n  local seen = {}\n  for _, mark in ipairs(marks) do\n    if seen[mark] then\n      return true\n    end\n    seen[mark] = true\n  end\n  return false\nend\n\nlocal function counts_of(words)\n  local counts = {}\n  for _, word in ipairs(words) do\n    counts[word] = (counts[word] or 0) + 1\n  end\n  return counts\nend\n\nprint(has_duplicate({1, 2, 1}), counts_of({\"a\", \"b\", \"a\"})[\"a\"])\n" },
        { "near.php", "<?php\nfunction hasDuplicate(array $marks): bool\n{\n    $seen = [];\n    foreach ($marks as $mark) {\n        if (isset($seen[$mark])) {\n            return true;\n        }\n        $seen[$mark] = true;\n    }\n    return false;\n}\n\nfunction countsOf(array $words): array\n{\n    $counts = [];\n    foreach ($words as $word) {\n        $counts[$word] = ($counts[$word] ?? 0) + 1;\n    }\n    return $counts;\n}\n\nvar_dump(hasDuplicate([1, 2, 1]), countsOf([\"a\", \"b\", \"a\"]));\n" },
        { "near.pl", "use strict;\nuse warnings;\n\nsub has_duplicate {\n    my @marks = @_;\n    my %seen;\n    foreach my $mark (@marks) {\n        return 1 if $seen{$mark};\n        $seen{$mark} = 1;\n    }\n    return 0;\n}\n\nsub counts_of {\n    my @words = @_;\n    my %counts;\n    foreach my $word (@words) {\n        $counts{$word} = ($counts{$word} // 0) + 1;\n    }\n    return %counts;\n}\n\nmy %counted = counts_of(\"a\", \"b\", \"a\");\nprint has_duplicate(1, 2, 1), \" \", $counted{\"a\"}, \"\\n\";\n" },
        { "near.ps1", "function Test-HasDuplicate($marks) {\n    $seen = @{}\n    foreach ($mark in $marks) {\n        if ($seen.ContainsKey($mark)) {\n            return $true\n        }\n        $seen[$mark] = $true\n    }\n    return $false\n}\n\nfunction Get-CountsOf($words) {\n    $counts = @{}\n    foreach ($word in $words) {\n        $counts[$word] = $counts[$word] + 1\n    }\n    return $counts\n}\n\nTest-HasDuplicate @(1, 2, 1)\n(Get-CountsOf @(\"a\", \"b\", \"a\"))[\"a\"]\n" },
        { "near.py", "def has_duplicate(marks):\n    seen = set()\n    for mark in marks:\n        if mark in seen:\n            return True\n        seen.add(mark)\n    return False\n\n\ndef counts_of(words):\n    counts = {}\n    for word in words:\n        counts[word] = counts.get(word, 0) + 1\n    return counts\n\n\nprint(has_duplicate([1, 2, 1]), counts_of([\"a\", \"b\", \"a\"]))\n" },
        { "near.rb", "require \"set\"\n\ndef duplicate?(marks)\n  seen = Set.new\n  marks.each do |mark|\n    return true if seen.include?(mark)\n    seen << mark\n  end\n  false\nend\n\ndef counts_of(words)\n  counts = Hash.new(0)\n  words.each do |word|\n    counts[word] = counts[word] + 1\n  end\n  counts\nend\n\np duplicate?([1, 2, 1]), counts_of(%w[a b a])\n" },
        { "near.rs", "use std::collections::{HashMap, HashSet};\n\nfn has_duplicate(marks: &[i32]) -> bool {\n    let mut seen = HashSet::new();\n    for mark in marks {\n        if !seen.insert(*mark) {\n            return true;\n        }\n    }\n    false\n}\n\nfn counts_of(words: &[&str]) -> HashMap<String, i32> {\n    let mut counts = HashMap::new();\n    for word in words {\n        *counts.entry(word.to_string()).or_insert(0) += 1;\n    }\n    counts\n}\n\nfn main() {\n    println!(\"{} {:?}\", has_duplicate(&[1, 2, 1]), counts_of(&[\"a\", \"b\", \"a\"]).get(\"a\"));\n}\n" },
        { "Near.scala", "import scala.collection.mutable\n\nobject Near {\n  def hasDuplicate(marks: List[Int]): Boolean = {\n    val seen = mutable.Set[Int]()\n    for (mark <- marks) {\n      if (!seen.add(mark)) {\n        return true\n      }\n    }\n    false\n  }\n\n  def countsOf(words: List[String]): Map[String, Int] = {\n    val counts = mutable.Map[String, Int]()\n    for (word <- words) {\n      counts(word) = counts.getOrElse(word, 0) + 1\n    }\n    counts.toMap\n  }\n\n  def main(args: Array[String]): Unit = {\n    println(s\"${hasDuplicate(List(1, 2, 1))} ${countsOf(List(\"a\", \"b\", \"a\"))}\")\n  }\n}\n" },
        { "near.ts", "function hasDuplicate(marks: number[]): boolean {\n  const seen = new Set<number>();\n  for (const mark of marks) {\n    if (seen.has(mark)) {\n      return true;\n    }\n    seen.add(mark);\n  }\n  return false;\n}\n\nfunction countsOf(words: string[]): Record<string, number> {\n  const counts: Record<string, number> = {};\n  for (const word of words) {\n    counts[word] = (counts[word] || 0) + 1;\n  }\n  return counts;\n}\n\nconsole.log(hasDuplicate([1, 2, 1]), countsOf([\"a\", \"b\", \"a\"]));\n" },
