    [Theory]
    [MemberData(nameof(Found))]
    public void AListFilledAndNeverReadIsFound(string fileName, string code, string said)
    {
        Assert.Equal([said], Scanned(fileName, code).Select(finding => $"{finding.Line}|{finding.PatternId}|{finding.Message}"));
    }

    [Theory]
    [MemberData(nameof(Changed))]
    public void TheChangeGivesBackTheListTheFunctionBuilt(string fileName, string code, string changed)
    {
        var finding = Assert.Single(Scanned(fileName, code));

        Assert.NotNull(finding.Fix);
        Assert.Equal(changed, string.Join("\n", finding.Fix.ApplyTo(Source(fileName, code)) ?? []));
    }

    [Theory]
    [MemberData(nameof(FoundWithNoChange))]
    public void NoChangeIsOfferedWhereGivingBackTheListIsNotClearlyMeant(string fileName, string code, string said)
    {
        var finding = Assert.Single(Scanned(fileName, code));

        Assert.Equal(said, $"{finding.Line}|{finding.PatternId}|{finding.Message}");
        Assert.Null(finding.Fix);
    }

    [Theory]
    [MemberData(nameof(NearMisses))]
    public void AListThatIsReadIsLeftAlone(string fileName, string code)
    {
        Assert.Empty(Scanned(fileName, code));
    }
}
